const GDN_K2_DYNAMIC_SHARED_BYTES: u32 = 67_072;

/// The default dynamic-shared-memory launch bound the naive SDPA family lives under: past
/// `T_kv * 4 > 48KB` (T_kv > 12288) the smem kernel cannot launch — the measured
/// dspark/full-attn long-ctx crash class. `sdpa_naive` dispatches to the byte-identical
/// gmem-scores twin above this line.
const SDPA_NAIVE_SMEM_MAX: usize = 48 * 1024;

/// Guard on the gmem twin's `n_head * T * T_kv * 4`-byte scores workspace. The shapes that
/// legitimately hit the smem bound are tall-KV blocks (T <= draft block size), which land in
/// the tens of MB; 1 GiB refuses a square T==T_kv misuse before it silently eats the card.
const SDPA_NAIVE_GMEM_WS_MAX: usize = 1 << 30;

#[cfg(debug_assertions)]
pub(crate) fn debug_assert_tensor_stream_device<T>(
    tensor: &CudaSlice<T>,
    stream: &CudaStream,
    site: &str,
) {
    let tensor_dev = tensor.ordinal();
    let stream_dev = stream.context().ordinal();
    assert_eq!(
        tensor_dev, stream_dev,
        "PP cross-device tensor read at {site}: tensor on dev{tensor_dev}, stream on dev{stream_dev}"
    );
}

fn ensure_tensor_stream_device<T>(
    tensor: &impl DeviceSlice<T>,
    stream: &CudaStream,
    site: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let tensor_dev = tensor.stream().context().ordinal();
    let stream_dev = stream.context().ordinal();
    if tensor_dev != stream_dev {
        return Err(format!(
            "PP cross-device tensor access at {site}: tensor on dev{tensor_dev}, \
             stream on dev{stream_dev}"
        )
        .into());
    }
    Ok(())
}

