/// One line, once, when the ILP door is armed but the expert layout is not the interleaved
/// NVFP4 it was written for: a silent fall-through would let a box A/B read the door's absence.
fn moe_vrows_ilp_refuse(site: &str, qt: i32) {
    static SAID: std::sync::Once = std::sync::Once::new();
    SAID.call_once(|| {
        eprintln!(
            "[moe-vrows-ilp] REFUSED at {site}: MEMRA_MOE_VROWS_ILP is on but the expert qtype is \
             {qt}, neither QT_NVFP4 ({QT_NVFP4}) nor QT_NVFP4_V2 ({QT_NVFP4_V2}); the shipped \
             kernel runs (the ILP twins hoist the NVFP4 group loads, interleaved or slot-major, \
             and no other layout)"
        );
    });
}

