    /// Heterogeneous serving-batch penalties over host-maintained sparse window counts.
    /// `offsets[r]..offsets[r+1]` indexes the unique positive-count `(id,count)` entries for logits row
    /// `rows[r]`; each row may carry independent repetition/frequency/presence coefficients.
    /// One thread owns one distinct logit, so the kernel needs neither atomics nor the
    /// history-squared dedup scan used by the speculative raw-history oracle.
    #[allow(clippy::too_many_arguments)]
    pub fn penalize_logits_sparse_rows(
        &self,
        x: &mut CudaSlice<f32>,
        ids: &[u32],
        counts: &[u32],
        offsets: &[i32],
        rows: &[i32],
        reps: &[f32],
        freqs: &[f32],
        presents: &[f32],
        n: usize,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let nrow = rows.len();
        if nrow == 0 {
            return Ok(());
        }
        let _ni = i32::try_from(n).map_err(|_| "sparse penalty logits width must fit CUDA i32")?;
        let _nr = i32::try_from(nrow).map_err(|_| "sparse penalty row count must fit CUDA i32")?;
        let entry_count =
            i32::try_from(ids.len()).map_err(|_| "sparse penalty entry count must fit CUDA i32")?;
        if ids.len() != counts.len()
            || offsets.len() != nrow + 1
            || reps.len() != nrow
            || freqs.len() != nrow
            || presents.len() != nrow
            || offsets.first().copied() != Some(0)
            || offsets.last().copied() != Some(entry_count)
        {
            return Err("sparse penalty row metadata shape mismatch".into());
        }
        if counts.contains(&0) {
            return Err("sparse penalty counts must be positive".into());
        }
        let mut max_len = 0usize;
        for pair in offsets.windows(2) {
            if pair[0] < 0 || pair[1] < pair[0] {
                return Err("sparse penalty offsets must be monotonic".into());
            }
            max_len = max_len.max((pair[1] - pair[0]) as usize);
        }
        if max_len == 0 {
            return Ok(());
        }

        let mut seen = std::collections::HashSet::with_capacity(ids.len());
        for (r, &row) in rows.iter().enumerate() {
            if row < 0 || (row as usize + 1).saturating_mul(n) > x.len() {
                return Err("sparse penalty row index exceeds logits shape".into());
            }
            let begin = offsets[r] as usize;
            let end = offsets[r + 1] as usize;
            for &id in &ids[begin..end] {
                if id as usize >= n {
                    return Err("sparse penalty token id exceeds logits row".into());
                }
                if !seen.insert((row, id)) {
                    return Err("sparse penalty entries must be unique per logits row".into());
                }
            }
        }

        // SAFETY: the checks above establish every invariant of the launch-only helper.
        unsafe {
            self.penalize_logits_sparse_rows_unchecked(
                x, ids, counts, offsets, rows, reps, freqs, presents, n,
            )
        }
    }

    /// Launch-only form for the serving hot path, whose `HashMap`-backed producer already
    /// guarantees unique ids and whose rows are enumerated from the live batch.
    ///
    /// # Safety
    ///
    /// Shapes must match the safe wrapper, offsets must be monotonic and in bounds, every row
    /// must index `x`, and each `(row,id)` pair must occur at most once. Token ids outside the
    /// logits row are safe no-ops because the kernel bounds-checks them before computing `x`.
    #[allow(clippy::too_many_arguments)]
    pub(crate) unsafe fn penalize_logits_sparse_rows_unchecked(
        &self,
        x: &mut CudaSlice<f32>,
        ids: &[u32],
        counts: &[u32],
        offsets: &[i32],
        rows: &[i32],
        reps: &[f32],
        freqs: &[f32],
        presents: &[f32],
        n: usize,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let nrow = rows.len();
        if nrow == 0 {
            return Ok(());
        }
        let max_len = offsets
            .windows(2)
            .map(|pair| (pair[1] - pair[0]) as usize)
            .max()
            .unwrap_or(0);
        if max_len == 0 {
            return Ok(());
        }
        let ids_d = self.htod_u32_v(ids)?;
        let counts_d = self.htod_u32_v(counts)?;
        let offsets_d = self.htod_i32(offsets)?;
        let rows_d = self.htod_i32(rows)?;
        let reps_d = self.htod(reps)?;
        let freqs_d = self.htod(freqs)?;
        let presents_d = self.htod(presents)?;
        let f = self.func("penalize_logits_sparse_rows_f32");
        let ni = i32::try_from(n).map_err(|_| "sparse penalty logits width must fit CUDA i32")?;
        let nr = i32::try_from(nrow).map_err(|_| "sparse penalty row count must fit CUDA i32")?;
        let cfg = LaunchConfig {
            grid_dim: (max_len.div_ceil(128) as u32, nrow as u32, 1),
            block_dim: (128, 1, 1),
            shared_mem_bytes: 0,
        };
        let __s_b = self.gpu.stream();
        let mut b = __s_b.launch_builder(&f);
        b.arg(&mut *x)
            .arg(&ids_d)
            .arg(&counts_d)
            .arg(&offsets_d)
            .arg(&rows_d)
            .arg(&reps_d)
            .arg(&freqs_d)
            .arg(&presents_d)
            .arg(&ni)
            .arg(&nr);
        unsafe {
            b.launch(cfg)?;
        }
        Ok(())
    }

    /// ROW-INCREMENTAL penalties (dspark penalized-sampled admission): row r of `x`
    /// penalizes over the last `min(win, n_hist0 + r)` entries of `hist[..n_hist0 + r]`,
    /// where `hist` = [session window (n_hist0) ++ per-row drafted tokens (nrow-1)]. This
    /// is the within-round evolving penalty state block drafting needs: verify row r's
    /// target is penalized by every token committed before it INCLUDING same-round
    /// accepts — `penalize_logits_rows` (one shared window) is the frozen-window
    /// approximation this exists to replace on the dspark route.
    #[allow(clippy::too_many_arguments)]
    pub fn penalize_logits_rows_inc(
        &self,
        x: &mut CudaSlice<f32>,
        hist: &CudaSlice<u32>,
        n_hist0: usize,
        rep: f32,
        freq: f32,
        present: f32,
        n: usize,
        nrow: usize,
        win: usize,
    ) -> Result<(), Box<dyn std::error::Error>> {
        if nrow == 0 || win == 0 || (n_hist0 == 0 && nrow == 1) {
            return Ok(());
        }
        debug_assert!(
            hist.len() >= n_hist0 + nrow - 1,
            "rows-inc hist must carry n_hist0 + nrow - 1 ids"
        );
        let f = self.func("penalize_logits_rows_inc_f32");
        let max_len = win.min(n_hist0 + nrow - 1).max(1);
        let (nh, ni, nr, wi) = (n_hist0 as i32, n as i32, nrow as i32, win as i32);
        let cfg = LaunchConfig {
            grid_dim: (max_len.div_ceil(128) as u32, nrow as u32, 1),
            block_dim: (128, 1, 1),
            shared_mem_bytes: 0,
        };
        let __s_b = self.gpu.stream();
        let mut b = __s_b.launch_builder(&f);
        b.arg(&mut *x)
            .arg(hist)
            .arg(&nh)
            .arg(&rep)
            .arg(&freq)
            .arg(&present)
            .arg(&ni)
            .arg(&nr)
            .arg(&wi);
        unsafe {
            b.launch(cfg)?;
        }
        Ok(())
    }

    /// WEIGHT PREFETCH (SOTA item 3, 2026-07-13, DEFAULT ON): during a bandwidth-idle
    /// window (the fa launch reads KV, not weights) prefetch the NEXT matvec's
    /// decode-plane bytes into L2 so it reads L2-warm. Value-free scheduling op — same
    /// class as prefetch_l2 (numerics untouched by construction). Wired only where it
    /// measured positive: the E4B dc attn arm (+0.65%). 26B (flat — MoE ffn dominates),
    /// 31B (−0.2% — decode at the DRAM wall) and the ffn gate/up cascade (−1% — 29MB/layer
    /// floods the fill path) all probed and NOT wired. MEMRA_WPF=0 rollback seam.
    pub fn wpf_level() -> u32 {
        static ON: std::sync::OnceLock<u32> = std::sync::OnceLock::new();
        *ON.get_or_init(|| {
            std::env::var("MEMRA_WPF")
                .ok()
                .and_then(|v| v.parse().ok())
                .unwrap_or(1)
        })
    }

    /// PDL launch arm (SOTA item 2, 2026-07-13, DEFAULT ON): the six MEMRA_PDL_ENTRY glue
    /// kernels launch through cuLaunchKernelEx with PROGRAMMATIC_STREAM_SERIALIZATION — the
    /// grid launches while the predecessor drains (~120ns/kernel back, pdl_probe), the
    /// kernels' entry grid-dep sync restores read order (SASS-audited: ACQBULK precedes
    /// every LDG in all six). Valid windows: E4B +1.0-1.2% (128 AND 384-tok gens);
    /// 26B/31B/qwen flat no-harm. Battery: kernel-check GREEN, run-gen tokens IDENTICAL x3
    /// gemma, spec 64/64 E4B K=1/4/8 + 26B/31B K=4 + qwen PASS. Works eager AND under
    /// capture (capture encodes native programmatic edges — the post-capture edge-REWRITE
    /// arm died: engine graphs hold cuMemAllocAsync alloc nodes, edge edits on those return
    /// CUDA_ERROR_NOT_SUPPORTED). MEMRA_PDL=0 rollback seam.
    /// See the `verify_exact` field. Scoped by the dflash round around its t=16 verify.
    /// Prefer `exact_scope` — the RAII form — anywhere a `?` can exit the scope: a manual
    /// true/false pair leaves the flag LATCHED engine-wide when an error propagates
    /// between the two calls (hermes finding on dspark_spec_session_burst, fixed
    /// 2026-08-23), and every later request then runs the exact-GEMM program.
    pub fn set_verify_exact(&self, on: bool) {
        self.verify_exact
            .store(on, std::sync::atomic::Ordering::Relaxed);
    }
    pub(crate) fn verify_exact_on(&self) -> bool {
        self.verify_exact.load(std::sync::atomic::Ordering::Relaxed)
    }

    /// RAII scope over `verify_exact`: sets the flag to `on` now and restores the
    /// PREVIOUS value on drop — unwind, early `return`, and every `?` exit included.
    /// This is the required form for any scope an error can leave (see
    /// `set_verify_exact`); dropping the guard early (`drop(scope)`) ends the scope
    /// exactly where the manual `set_verify_exact(false)` used to sit.
    pub fn exact_scope(&self, on: bool) -> ExactScope<'_> {
        ExactScope::set(&self.verify_exact, on)
    }

