    pub fn silu_mul_scaled_q8_1_sel_into(
        &self,
        gate: &CudaSlice<f32>,
        up: &CudaSlice<f32>,
        gmac: &CudaSlice<f32>,
        umac: &CudaSlice<f32>,
        sel: &CudaSlice<i32>,
        limit: Option<f32>,
        out_q: &mut CudaSlice<i8>,
        out_d: &mut CudaSlice<f32>,
        n_per: usize,
        n_sel: usize,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let n = n_per * n_sel;
        if !n_per.is_multiple_of(32) || out_q.len() < n || out_d.len() < n / 32 {
            return Err(format!(
                "silu sel geometry n_per={n_per} n_sel={n_sel} q={} d={}",
                out_q.len(),
                out_d.len()
            )
            .into());
        }
        if let Some(limit) = limit {
            if limit <= 1e-6 {
                return Err(format!(
                    "silu sel clamp limit {limit} is at or below the 1e-6 eps gate"
                )
                .into());
            }
            let f = self.func("silu_mul_scaled_q8_1_sel_clamp");
            let cfg = LaunchConfig::for_num_elems(n as u32);
            let (np, ns) = (n_per as i32, n_sel as i32);
            let __s_b = self.gpu.stream();
            let mut b = __s_b.launch_builder(&f);
            b.arg(gate)
                .arg(up)
                .arg(gmac)
                .arg(umac)
                .arg(sel)
                .arg(&limit)
                .arg(out_q)
                .arg(out_d)
                .arg(&np)
                .arg(&ns);
            unsafe {
                b.launch(cfg)?;
            }
            return Ok(());
        }
        let f = self.func("silu_mul_scaled_q8_1_sel");
        let cfg = LaunchConfig::for_num_elems(n as u32);
        let (np, ns) = (n_per as i32, n_sel as i32);
        let __s_b = self.gpu.stream();
        let mut b = __s_b.launch_builder(&f);
        b.arg(gate)
            .arg(up)
            .arg(gmac)
            .arg(umac)
            .arg(sel)
            .arg(out_q)
            .arg(out_d)
            .arg(&np)
            .arg(&ns);
        unsafe {
            b.launch(cfg)?;
        }
        Ok(())
    }

