    /// Door `MEMRA_GLM5_Q8_FUSE` (lane/b200-q8-fuse-20260902): RMSNorm emitting BOTH the f32
    /// normed row `z` (needed by callers that also read the un-quantized row — the MoE router
    /// logits, an ungated shared-expert path) AND its q8_1 quantization (int8 qs + per-32 f32
    /// scale), in one launch. Removes the standalone `quantize_q8_1(&z, ...)` launch a caller
    /// would otherwise issue against the identical bytes. BIT-IDENTICAL to
    /// `rms_norm(x,w,&mut z,ncols,nrows,eps)` then `quantize_q8_1(&z,nrows,ncols)` — see
    /// `rms_norm_zq8_f32`'s header in cu/kernels.cu for the identity argument. MUST launch at
    /// `rms_block()`, the SAME blockDim `rms_norm` uses: the sum-of-squares block-reduce tree
    /// depends on blockDim (per-thread stride, shfl-tree depth), so a fixed 1024 would diverge
    /// from `rms_norm`'s actual per-model blockDim (256 by default; 1024 only where a loader
    /// overrides `RMS_BLOCK_DEFAULT`, e.g. gemma4) — caught by `q8_fuse_gate`'s ncols=1536 shape
    /// before this landed (README: keep this dynamic, never hardcode the block size again).
    pub fn rms_norm_zq8_f32(
        &self,
        x: &CudaSlice<f32>,
        w: &CudaSlice<f32>,
        z: &mut CudaSlice<f32>,
        ncols: usize,
        nrows: usize,
        eps: f32,
    ) -> Result<(CudaSlice<i8>, CudaSlice<f32>), Box<dyn std::error::Error>> {
        self.rms_norm_zq8_f32_arm(x, w, z, ncols, nrows, eps, Self::norm_ilp_zq8_on())
    }

    /// `MEMRA_HC_MIXES_KERNEL=1` (lane/hc-mixes-gemv-20260905): the hyper-connection mixes
    /// projection at t=1 through the native `hc_mixes_gemv_f32` kernel instead of cuBLASLt.
    /// NUMERIC CLASS (a different, fixed summation order), deterministic run to run. Default OFF
    /// pending its model-scale row.
    pub fn hc_mixes_kernel_on() -> bool {
        static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
        *ON.get_or_init(|| std::env::var("MEMRA_HC_MIXES_KERNEL").as_deref() == Ok("1"))
    }

    /// Native t=1 GEMV `y[r] = sum_k w[r*in_f + k] x[k]`, r < out_f, one block per row. Returns
    /// Ok(false) without launching when the shape does not fit (in_f must be 16 * 1024), so the
    /// caller runs the cuBLASLt path unchanged.
    pub fn hc_mixes_gemv_into(
        &self,
        x: &cudarc::driver::CudaView<'_, f32>,
        w: &cudarc::driver::CudaView<'_, f32>,
        y: &mut cudarc::driver::CudaViewMut<'_, f32>,
        in_f: usize,
        out_f: usize,
    ) -> Result<bool, Box<dyn std::error::Error>> {
        const BLOCK: usize = 1024;
        if in_f != 16 * BLOCK || out_f == 0 || out_f > 65535 {
            return Ok(false);
        }
        let f = self.func("hc_mixes_gemv_f32");
        let cfg = LaunchConfig {
            grid_dim: (out_f as u32, 1, 1),
            block_dim: (BLOCK as u32, 1, 1),
            shared_mem_bytes: 0,
        };
        let (inf, outf) = (in_f as i32, out_f as i32);
        let __s_b = self.gpu.stream();
        let mut b = __s_b.launch_builder(&f);
        b.arg(x).arg(w).arg(&mut *y).arg(&inf).arg(&outf);
        unsafe {
            b.launch(cfg)?;
        }
        Ok(true)
    }

    /// Native f32 row GEMV `y[j][r] = dot(w[r, :], x[j, :])` for `m` tokens (`gemv_f32_rows`,
    /// grid (out_f, m), block 256). Returns `Ok(false)` without launching when the shape does not
    /// fit: `in_f % 1024 != 0`, `in_f == 0`, `out_f == 0 || out_f > 65535`, `m == 0 || m > 16`.
    /// Deterministic and per-row identical for every m (verify == decode by construction);
    /// numeric class against cuBLASLt (`MEMRA_F32_GEMV_KERNEL`).
    pub fn gemv_f32_rows_into<I, O>(
        &self,
        x: &I,
        w: &I,
        y: &mut O,
        m: usize,
        in_f: usize,
        out_f: usize,
    ) -> Result<bool, Box<dyn std::error::Error>>
    where
        I: cudarc::driver::DevicePtr<f32>,
        O: cudarc::driver::DevicePtrMut<f32>,
    {
        const BLOCK: usize = 256;
        if in_f == 0
            || !in_f.is_multiple_of(4 * BLOCK)
            || out_f == 0
            || out_f > 65535
            || m == 0
            || m > 16
        {
            return Ok(false);
        }
        let f = self.func("gemv_f32_rows");
        let cfg = LaunchConfig {
            grid_dim: (out_f as u32, m as u32, 1),
            block_dim: (BLOCK as u32, 1, 1),
            shared_mem_bytes: 0,
        };
        let (inf, outf) = (in_f as i32, out_f as i32);
        let stream = self.gpu.stream();
        // raw pointers: the generic DevicePtr bounds (views, slices) are not launch args
        let (px, _gx) = x.device_ptr(&stream);
        let (pw, _gw) = w.device_ptr(&stream);
        let (py, _gy) = y.device_ptr_mut(&stream);
        let mut b = stream.launch_builder(&f);
        b.arg(&px).arg(&pw).arg(&py).arg(&inf).arg(&outf);
        unsafe {
            b.launch(cfg)?;
        }
        if F32_GEMV_KERNEL_DISPATCHES.fetch_add(1, std::sync::atomic::Ordering::Relaxed) == 0 {
            eprintln!(
                "[f32-gemv-kernel] engaged: f32 linear at m<=16 rides gemv_f32_rows instead of \
                 cuBLASLt (MEMRA_F32_GEMV_KERNEL=1; first shape {in_f}->{out_f} m={m})"
            );
        }
        Ok(true)
    }

    /// The arm-explicit form of [`Engine::rms_norm_zq8_f32`]: `ilp` selects the
    /// `rms_norm_zq8_f32_v2` twin (MEMRA_NORM_ILP and MEMRA_NORM_ILP_ZQ8, both default ON; four loads in flight per round
    /// in both passes, bit-identical by construction, see its header in cu/kernels.cu) over the
    /// v1 kernel. Public so the gate (`tests/norm_zq8_ilp_gpu.rs`) can run BOTH arms in one
    /// process; `norm_ilp_on()` is a process-lifetime latch and cannot be flipped mid-test.
    #[allow(clippy::too_many_arguments)]
    pub fn rms_norm_zq8_f32_arm(
        &self,
        x: &CudaSlice<f32>,
        w: &CudaSlice<f32>,
        z: &mut CudaSlice<f32>,
        ncols: usize,
        nrows: usize,
        eps: f32,
        ilp: bool,
    ) -> Result<(CudaSlice<i8>, CudaSlice<f32>), Box<dyn std::error::Error>> {
        assert!(ncols.is_multiple_of(32));
        let nblk = ncols / 32;
        let mut q = self.alloc_uninit::<i8>(nrows * ncols)?; // full-overwrite output
        let mut d = self.alloc_uninit::<f32>(nrows * nblk)?; // full-overwrite output
        let f = self.func(if ilp {
            "rms_norm_zq8_f32_v2"
        } else {
            "rms_norm_zq8_f32"
        });
        // One block per row, blockDim = rms_block() — MUST match `rms_norm`'s launch exactly
        // (see the doc comment above); the kernel body is blockDim-generic (rms_norm_f32's
        // reduce shape), so this is the only thing that has to track it.
        let cfg = LaunchConfig {
            grid_dim: (nrows as u32, 1, 1),
            block_dim: (rms_block(), 1, 1),
            shared_mem_bytes: 0,
        };
        let (nc, ep) = (ncols as i32, eps);
        let __s_b = self.gpu.stream();
        let mut b = __s_b.launch_builder(&f);
        b.arg(x)
            .arg(w)
            .arg(&mut *z)
            .arg(&mut q)
            .arg(&mut d)
            .arg(&nc)
            .arg(&ep);
        unsafe {
            b.launch(cfg)?;
        }
        Ok((q, d))
    }

    /// Slot-fed quantize_q8_1 twin (alloc-free capture lane).
    #[track_caller]
    pub fn quantize_q8_1_into(
        &self,
        x: &CudaSlice<f32>,
        m: usize,
        in_f: usize,
        q: &mut CudaSlice<i8>,
        d: &mut CudaSlice<f32>,
    ) -> Result<(), Box<dyn std::error::Error>> {
        q8_census_record(std::panic::Location::caller(), m, in_f);
        let nblk = in_f / 32;
        debug_assert!(q.len() >= m * in_f && d.len() >= m * nblk);
        let cfg = LaunchConfig::for_num_elems((m * in_f) as u32);
        let (inf, mi) = (in_f as i32, m as i32);
        if Self::pdl_on() && Self::pdl_wb_on() {
            use cudarc::driver::{DevicePtr, DevicePtrMut};
            let s = &self.gpu.stream();
            let (px, _g0) = x.device_ptr(s);
            let (pq, _g1) = q.device_ptr_mut(s);
            let (pd, _g2) = d.device_ptr_mut(s);
            let mut ps = [
                &px as *const _ as *mut std::ffi::c_void,
                &pq as *const _ as *mut _,
                &pd as *const _ as *mut _,
                &inf as *const _ as *mut _,
                &mi as *const _ as *mut _,
            ];
            unsafe {
                self.launch_pdl("quantize_q8_1", cfg.grid_dim, cfg.block_dim, &mut ps)?;
            }
            return Ok(());
        }
        let f = self.func("quantize_q8_1");
        let __s_b = self.gpu.stream();
        let mut b = __s_b.launch_builder(&f);
        b.arg(x).arg(&mut *q).arg(&mut *d).arg(&inf).arg(&mi);
        unsafe {
            b.launch(cfg)?;
        }
        Ok(())
    }

    /// DECODE GLUE-FUSION LEVER: `res = a+b; z = rms_norm(res)*w` with z emitted as q8_1. `res` is
    /// still written (the post-ffn residual add reads it). Fuses add_rms_norm + quantize_q8_1.
    /// Returns (out_q, out_d) for matmul_pre. BIT-IDENTICAL. ncols % 32 == 0.
    #[allow(clippy::too_many_arguments)] // allow: the parameter list mirrors the kernel/FFI/call contract; bundling into a struct is a refactor, not a lint fix
    pub fn add_rms_norm_q8_1(
        &self,
        a: &CudaSlice<f32>,
        b_in: &CudaSlice<f32>,
        w: &CudaSlice<f32>,
        res: &mut CudaSlice<f32>,
        ncols: usize,
        nrows: usize,
        eps: f32,
    ) -> Result<(CudaSlice<i8>, CudaSlice<f32>), Box<dyn std::error::Error>> {
        let nblk = ncols / 32;
        let mut q = self.alloc_uninit::<i8>(nrows * ncols)?;
        let mut d = self.alloc_uninit::<f32>(nrows * nblk)?;
        let f = self.func("add_rms_norm_q8_1");
        // 1024 threads: same single-CTA-at-decode reasoning as rms_norm_q8_1.
        let cfg = LaunchConfig {
            grid_dim: (nrows as u32, 1, 1),
            block_dim: (1024, 1, 1),
            shared_mem_bytes: 0,
        };
        let (nc, e) = (ncols as i32, eps);
        let __s_bld = self.gpu.stream();
        let mut bld = __s_bld.launch_builder(&f);
        bld.arg(a)
            .arg(b_in)
            .arg(w)
            .arg(res)
            .arg(&mut q)
            .arg(&mut d)
            .arg(&nc)
            .arg(&e);
        unsafe {
            bld.launch(cfg)?;
        }
        Ok((q, d))
    }

    /// RANK3 LEVER (add+rmsnorm fuse): `res = a + b; dst = rms_norm(res) * w` in ONE launch. Fuses
    /// e.add(a,b,res) + e.rms_norm(res,w,dst), removing one launch + one HBM read of the residual per
    /// residual+norm pair. BIT-IDENTICAL to the two-kernel sequence (same IEEE add, same reduction).
    /// O-PROJ TAIL FUSION M2: mixed = a0+a1 composed in-register, then the VERBATIM
    /// add_rms_norm program. Raw UVA pointers for the join partials (persistent ws rows).
    #[allow(clippy::too_many_arguments)]
    pub fn join_add_rms_norm_raw(
        &self,
        a0_raw: u64,
        a1_raw: u64,
        x: &CudaSlice<f32>,
        w: &CudaSlice<f32>,
        res: &mut CudaSlice<f32>,
        dst: &mut CudaSlice<f32>,
        ncols: usize,
        eps: f32,
    ) -> Result<(), Box<dyn std::error::Error>> {
        if a0_raw == 0 || a1_raw == 0 || x.len() < ncols || res.len() < ncols || dst.len() < ncols {
            return Err("join_add_rms_norm geometry".into());
        }
        let f = self.func("join_add_rms_norm_f32");
        let cfg = LaunchConfig {
            grid_dim: (1, 1, 1),
            block_dim: (rms_block(), 1, 1),
            shared_mem_bytes: 0,
        };
        let (nc, e) = (ncols as i32, eps);
        let __s_b = self.gpu.stream();
        let mut b = __s_b.launch_builder(&f);
        b.arg(&a0_raw)
            .arg(&a1_raw)
            .arg(x)
            .arg(w)
            .arg(&mut *res)
            .arg(&mut *dst)
            .arg(&nc)
            .arg(&e);
        unsafe {
            b.launch(cfg)?;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)] // allow: the parameter list mirrors the kernel/FFI/call contract; bundling into a struct is a refactor, not a lint fix
    pub fn add_rms_norm(
        &self,
        a: &CudaSlice<f32>,
        b: &CudaSlice<f32>,
        w: &CudaSlice<f32>,
        res: &mut CudaSlice<f32>,
        dst: &mut CudaSlice<f32>,
        ncols: usize,
        nrows: usize,
        eps: f32,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let (nc, e) = (ncols as i32, eps);
        let kname = if Self::norm_ilp_on() {
            "add_rms_norm_f32_v2"
        } else {
            "add_rms_norm_f32"
        };
        if Self::pdl_on() && Self::pdl_wb_on() {
            use cudarc::driver::{DevicePtr, DevicePtrMut};
            let s = &self.gpu.stream();
            let (pa, _g0) = a.device_ptr(s);
            let (pb, _g1) = b.device_ptr(s);
            let (pw, _g2) = w.device_ptr(s);
            let (pr, _g3) = res.device_ptr_mut(s);
            let (pd, _g4) = dst.device_ptr_mut(s);
            let mut ps = [
                &pa as *const _ as *mut std::ffi::c_void,
                &pb as *const _ as *mut _,
                &pw as *const _ as *mut _,
                &pr as *const _ as *mut _,
                &pd as *const _ as *mut _,
                &nc as *const _ as *mut _,
                &e as *const _ as *mut _,
            ];
            unsafe {
                self.launch_pdl(kname, (nrows as u32, 1, 1), (rms_block(), 1, 1), &mut ps)?;
            }
            return Ok(());
        }
        let f = self.func(kname);
        let cfg = LaunchConfig {
            grid_dim: (nrows as u32, 1, 1),
            block_dim: (rms_block(), 1, 1),
            shared_mem_bytes: 0,
        };
        let __s_b2 = self.gpu.stream();
        let mut b2 = __s_b2.launch_builder(&f);
        b2.arg(a)
            .arg(b)
            .arg(w)
            .arg(&mut *res)
            .arg(&mut *dst)
            .arg(&nc)
            .arg(&e);
        unsafe {
            b2.launch(cfg)?;
        }
        Ok(())
    }

