    /// BF16 twin of `matvec_f32_qkv_into` (weights as raw checkpoint bf16 bytes).
    #[allow(clippy::too_many_arguments)]
    /// T-COLUMN twin of `matvec_bf16_qkvg_into` (spec verify): weights read once, T input
    /// columns accumulated with per-column FP order identical to the t=1 kernel. Outputs
    /// land column-major-of-rows: yq[c*out_q + row] etc.
    #[allow(clippy::too_many_arguments)]
    pub fn matvec_bf16_qkvg_tcol_into(
        &self,
        wq: &CudaSlice<u8>,
        wk: &CudaSlice<u8>,
        wv: &CudaSlice<u8>,
        wg: &CudaSlice<u8>,
        x_t: &CudaSlice<f32>,
        yq: &mut CudaSlice<f32>,
        yk: &mut CudaSlice<f32>,
        yv: &mut CudaSlice<f32>,
        yg: &mut CudaSlice<f32>,
        in_f: usize,
        out_q: usize,
        out_kv: usize,
        out_g: usize,
        t: usize,
    ) -> Result<(), Box<dyn std::error::Error>> {
        if t == 0
            || t > 8
            || !in_f.is_multiple_of(8)
            || x_t.len() < t * in_f
            || yq.len() < t * out_q
            || yk.len() < t * out_kv
            || yv.len() < t * out_kv
            || (out_g > 0 && yg.len() < t * out_g)
        {
            return Err("matvec_bf16_qkvg_tcol geometry".into());
        }
        let grid = out_q + 2 * out_kv + out_g;
        let cfg = LaunchConfig {
            grid_dim: (grid as u32, 1, 1),
            block_dim: (mmv_block(), 1, 1),
            shared_mem_bytes: 0,
        };
        let (ini, oq, okv, og, ti) = (
            in_f as i32,
            out_q as i32,
            out_kv as i32,
            out_g as i32,
            t as i32,
        );
        let __s_b = self.gpu.stream();
        // One runtime-T program for every live width. The compile-time 2/4/8 twins are
        // retained in the fatbin as research controls, but dispatching them by the current
        // batch width changes kernels inside a request when peers arrive or retire. That is
        // a load-history numeric-program switch, and their pre-twin TOKFP receipts did not
        // qualify it (Hermes `64fa2b55baf0d887`).
        let f = self.func("matvec_bf16_qkvg_tcol");
        let mut b = __s_b.launch_builder(&f);
        b.arg(wq)
            .arg(wk)
            .arg(wv)
            .arg(wg)
            .arg(x_t)
            .arg(yq)
            .arg(yk)
            .arg(yv)
            .arg(yg)
            .arg(&ini)
            .arg(&oq)
            .arg(&okv)
            .arg(&og)
            .arg(&ti);
        unsafe {
            b.launch(cfg)?;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)] // allow: the parameter list mirrors the kernel/FFI/call contract; bundling into a struct is a refactor, not a lint fix
    pub fn matvec_bf16_qkvg_into(
        &self,
        wq: &CudaSlice<u8>,
        wk: &CudaSlice<u8>,
        wv: &CudaSlice<u8>,
        wg: &CudaSlice<u8>,
        x: &CudaSlice<f32>,
        yq: &mut CudaSlice<f32>,
        yk: &mut CudaSlice<f32>,
        yv: &mut CudaSlice<f32>,
        yg: &mut CudaSlice<f32>,
        in_f: usize,
        out_q: usize,
        out_kv: usize,
        out_g: usize,
    ) -> Result<(), Box<dyn std::error::Error>> {
        if !in_f.is_multiple_of(8)
            || wq.len() != out_q * in_f * 2
            || wk.len() != out_kv * in_f * 2
            || wv.len() != out_kv * in_f * 2
            || wg.len() < out_g * in_f * 2
            || x.len() < in_f
            || yq.len() < out_q
            || yk.len() < out_kv
            || yv.len() < out_kv
            || (out_g > 0 && yg.len() < out_g)
        {
            return Err(format!(
                "fused bf16 QKV geometry in={in_f} out_q={out_q} out_kv={out_kv} out_g={out_g}"
            )
            .into());
        }
        let f = self.func("matvec_bf16_qkvg");
        let cfg = LaunchConfig {
            grid_dim: ((out_q + 2 * out_kv + out_g) as u32, 1, 1),
            block_dim: (mmv_block(), 1, 1),
            shared_mem_bytes: 0,
        };
        let (inf, oq, okv, og) = (in_f as i32, out_q as i32, out_kv as i32, out_g as i32);
        let __s_b = self.gpu.stream();
        let mut b = __s_b.launch_builder(&f);
        b.arg(wq)
            .arg(wk)
            .arg(wv)
            .arg(wg)
            .arg(x)
            .arg(yq)
            .arg(yk)
            .arg(yv)
            .arg(yg)
            .arg(&inf)
            .arg(&oq)
            .arg(&okv)
            .arg(&og);
        unsafe {
            b.launch(cfg)?;
        }
        Ok(())
    }

